function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
async function json(url,timeout=18000){const r=await fetch(url,{signal:AbortSignal.timeout(timeout)});if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json();}
function regionData(r){
 if(state.mode==='scenario'){const inputs={...r.scenario,future:r.scenario.future*state.rainFactor,past:r.scenario.past*state.rainFactor};return {inputs,result:scoreRisk(inputs),scenario:true,nasa:null,weather:null};}
 const record=state.records[r.id];const nasa=record?.nasa?parseNASA(record.nasa):{past:null,rows:[]};
 const at=record?.weatherAt||state.manifest?.fetchedAt;const weather=record?.weather?parseWeather(record.weather,Date.parse(at)):{future:null,soil:null,elevation:null,hours:[]};
 // A snapshot is an assessment at its recorded retrieval time, not a live warning.
 const inputs={future:weather.future,past:nasa.past,soil:weather.soil,elevation:weather.elevation,riverRise:null};
 return {inputs,result:scoreRisk(inputs),scenario:false,nasa,weather,at};
}
function appearance(d){const x=d.result;if(x.coverage<.89)return {name:'Insufficient data',color:'#8d9b9f',soft:'#f0f3f3',value:'—',level:-1};const lo=levelFor(x.lower),hi=levelFor(x.upper);return {...LEVELS[lo],name:lo===hi?LEVELS[lo].name:LEVELS[lo].name+'–'+LEVELS[hi].name,value:d.scenario?x.score:x.lower+'–'+x.upper,level:lo};}
function renderRegions(){
 $('#regionList').innerHTML=REGIONS.map(r=>{const a=appearance(regionData(r));return `<button class="region-button ${state.selected===r.id?'active':''}" data-region="${r.id}" aria-pressed="${state.selected===r.id}"><i class="region-dot" style="--c:${a.color}"></i><span><strong>${r.name}</strong><small>${r.subtitle}</small></span><span class="region-arrow">›</span></button>`;}).join('');
 $$('.region-button').forEach(b=>b.onclick=()=>selectRegion(b.dataset.region));
 $('#overviewBtn').classList.toggle('active',state.overview);
}
function selectRegion(id,fit=true){if(fit)$('#citySelect').value='';state.selected=id;state.overview=false;state.routes=[];if(!getRegion(id).local)state.layer='risk';render();if(fit)fitView();}
function renderHeader(){const r=getRegion(state.selected),local=state.layer!=='risk';$('#breadcrumb').textContent=state.overview?'Vietnam / All regions':`Vietnam / ${r.name}${local?' / Local view':''}`;$('#pageTitle').textContent=state.overview?'Vietnam flood outlook':local?r.name+', closer.':r.name;$('#pageSubtitle').textContent=state.overview?'Explore the regions. Zoom in to the places that matter.':local?'Explore places, water and the roads between them.':r.kind+' · '+r.point;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',b.dataset.mode===state.mode);});$('#scenarioControl').hidden=state.mode!=='scenario';$('#dataStatus').innerHTML=state.mode==='scenario'?'<span class="status-light" style="background:#c3a13e"></span> Illustrative storm · synthetic inputs':`<span class="status-light"></span> Source snapshot · ${state.lastRefresh|| (state.manifest?dateTime(state.manifest.fetchedAt):'loading')}`;$('#contextRight').textContent=state.mode==='scenario'?'Scenario only · not current conditions':'Experimental index · not a flood probability';$('#mapViewPill').textContent=state.overview?'Vietnam · 5 focus regions':local?r.name+' · '+(state.layer==='routes'?'Route comparison':'Infrastructure'):r.name+' · Regional view';$('#mapCaption').textContent=local?'Illustrative local sites'+(state.mode==='scenario'?' & flood zones':' · no observed inundation layer'):'Approximate study areas · point-based screening, not flood extents';$('#mapFooter').textContent=local?'Local positions and flood zones are for demonstration.':state.overview?'Select a region to inspect its data. Showing Hue details.':r.point+` · ${r.center[0].toFixed(3)}° N, ${r.center[1].toFixed(3)}° E`;$('#googleLink').href=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(state.overview?'Vietnam':r.name+' Vietnam')}`;$$('[data-layer]').forEach(b=>{const selected=b.dataset.layer===state.layer;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',selected);b.querySelector('.layer-check').textContent=selected?'✓':'';});}
function metric(icon,name,value,unit,source,detail,missing=false){return `<div class="metric ${missing?'missing':''}"><span class="metric-icon" aria-hidden="true">${icon}</span><div><div class="metric-name">${name}</div><div class="metric-source">${source}</div></div><div class="metric-value">${value} <small>${unit}</small>${detail?`<em>${detail}</em>`:''}</div></div>`;}
function renderDashboard(){const r=getRegion(state.selected),d=regionData(r),a=appearance(d),x=d.result;$('#detailTitle').textContent=r.name;$('#detailSubtitle').textContent=r.subtitle;$('#riskCard').innerHTML=`<div class="risk-card" style="--c:${a.color};--soft:${a.soft}"><div class="risk-top"><span class="risk-label"><i></i>${a.name}</span><span class="risk-type">${d.scenario?'SCENARIO':'SCREENING'}</span></div><div class="risk-value"><strong>${a.value}</strong><span>/ 100</span></div><div class="risk-scale" style="--position:${x.lower}%">${LEVELS.map(l=>`<i style="--c:${l.color}"></i>`).join('')}<b></b></div><p>${d.scenario?'Illustrative conditions. Change rainfall to explore how the index responds.':x.coverage<.89?'More source inputs are needed to calculate a useful interval.':`River rise is unknown. Its 10-point contribution gives this ${x.lower}–${x.upper} interval, not a probability.`}</p></div>`;
 $('#coverageLabel').textContent=d.scenario?'5 illustrative factors':`${x.factors.filter(f=>f.normalized!==null).length}/5 factors available`;
 const synthetic='Illustrative · not observed';const n=d.nasa,w=d.weather;
 $('#metrics').innerHTML=metric('☂','Previous rainfall',num(d.inputs.past,1),'mm',d.scenario?synthetic:'NASA POWER · model estimate',d.scenario?'72h total':`${compactDate(n?.start)}–${compactDate(n?.end)} UTC`)+metric('↗','Future rainfall',num(d.inputs.future,1),'mm',d.scenario?synthetic:'Open-Meteo · weather model','24h forecast')+metric('◒','Soil moisture',num(d.inputs.soil,2),'m³/m³',d.scenario?synthetic:'Open-Meteo · model, 0–1 cm',d.scenario?'scenario':'not SMAP')+metric('≋','River level',d.scenario?'Simulated':'Unavailable','',d.scenario?synthetic:'No gauged river feed connected',d.scenario?`rise +${num(d.inputs.riverRise,2)} m/h`:'not assumed to be zero',true)+metric('⌁','Elevation',num(d.inputs.elevation),'m',d.scenario?synthetic:'Open-Meteo · elevation metadata','reference point only');
 const shape=Array.from({length:24},(_,i)=>1+Math.sin(i/4-1)),shapeTotal=shape.reduce((a,b)=>a+b,0);const hours=d.scenario?shape.map((v,i)=>({rain:d.inputs.future*v/shapeTotal,time:i})):w?.hours||[];
 const max=Math.max(1,...hours.map(h=>h.rain||0));$('#rainChart').innerHTML=hours.length?hours.map((h,i)=>`<div class="bar" style="--h:${Math.max(3,(h.rain||0)/max*100)}%" title="${d.scenario?'Scenario hour '+(i+1):dateTime(h.time)}: ${num(h.rain,1)} mm"></div>`).join(''):'<span class="no-chart">Forecast not available</span>';
 $('#chartAxis').innerHTML=hours.length?`<span>${d.scenario?'Hour 1':dateTime(hours[0].time).split(',').at(-1)}</span><span>mm / hour</span><span>${d.scenario?'Hour 24':dateTime(hours.at(-1).time).split(',').at(-1)}</span>`:'';
 $('#chartSource').textContent=d.scenario?'Illustrative hourly distribution. No forecast claim.':`Open-Meteo forecast, evaluated at ${d.at?dateTime(d.at):'—'}.`;
 $('#qualityNote').innerHTML=d.scenario?'<b>Explore a scenario</b>All five inputs and local flood zones are synthetic. Switch to Source data to inspect the NASA response and forecast.':`<b>Know the data gap</b>${n?.end?'NASA rainfall ends '+compactDate(n.end)+' UTC. ':''}Weather and rainfall have different time windows. ${r.id==='north'?'This low-elevation heuristic does not model mountain flash floods.':'Tides, drainage and dam releases are not modelled.'} Regional colours do not establish street safety.`;
}
function initMap(){if(!window.L){$('#mapFallback').hidden=false;$('#mapFallback').innerHTML='<strong>Map component could not load.</strong><p>You can still select regions and inspect their data in the sidebar.</p>';return;}
 map=L.map('map',{zoomControl:false,zoomAnimation:false,fadeAnimation:false,minZoom:4,maxZoom:19,zoomSnap:.25,zoomDelta:.5,scrollWheelZoom:true}).setView([16.2,106.8],5.6);
 L.control.zoom({position:'bottomright'}).addTo(map);regionsLayer=L.layerGroup().addTo(map);facilitiesLayer=L.layerGroup().addTo(map);zonesLayer=L.layerGroup().addTo(map);routeLayer=L.layerGroup().addTo(map);
 installBasemaps(map,{select:$('#basemapSelect'),notify:toast});fitView();
}
function fitView(){if(!map)return;const r=getRegion(state.selected);if(state.overview)map.fitBounds([[8.35,102],[23.5,109.6]],{padding:[35,30]});else if(state.layer==='risk')map.fitBounds(r.outline,{padding:[65,65],maxZoom:r.zoom});else map.setView(r.localCenter,14);}
function renderMap(){if(!map)return;regionsLayer.clearLayers();facilitiesLayer.clearLayers();zonesLayer.clearLayers();routeLayer.clearLayers();const local=state.layer!=='risk',r=getRegion(state.selected);
 if(!local){for(const region of REGIONS){const d=regionData(region),a=appearance(d),selected=state.selected===region.id;if(state.showRisk)L.polygon(region.outline,{color:a.color,weight:selected?3:2,fillColor:a.color,fillOpacity:selected?.58:.43,dashArray:d.scenario?'':(d.result.score===null?'4 3':''),smoothFactor:1}).addTo(regionsLayer).on('click',()=>selectRegion(region.id)).bindTooltip(region.name+' · '+a.name,{sticky:true});L.marker(region.center,{icon:L.divIcon({className:`region-pin ${selected?'selected':''}`,html:`<span style="color:white;background:${a.color};border:2px solid white;border-radius:50%;width:100%;height:100%;display:grid;place-items:center;box-sizing:border-box">${d.result.coverage>=.89?d.scenario?d.result.score:d.result.lower+'+':'—'}</span>`,iconSize:[36,36],iconAnchor:[18,18]}),keyboard:true,title:region.name,alt:region.name+' region'}).addTo(regionsLayer).on('click',()=>selectRegion(region.id)).bindTooltip(region.name,{permanent:true,direction:['mekong','hue'].includes(region.id)?'left':'right',offset:['mekong','hue'].includes(region.id)?[-17,0]:[17,0],className:'region-tooltip'});}}
 else {if(state.mode==='scenario'&&state.showRisk){r.zones.forEach((z,i)=>L.circle([z.lat,z.lng],{radius:z.radius*Math.sqrt(state.rainFactor),color:LEVELS[z.level].color,weight:1,fillColor:LEVELS[z.level].color,fillOpacity:.48}).addTo(zonesLayer).bindTooltip(`Illustrative zone ${i+1} · ${LEVELS[z.level].name}`));}const places=examplePlaces[r.id];places.forEach(p=>L.marker([p.lat,p.lng],{icon:L.divIcon({className:'facility-pin '+p.kind,html:p.kind==='hospital'?'+':p.kind==='school'?'▥':p.kind==='home'?'⌂':'◇',iconSize:[24,24],iconAnchor:[12,12]}),title:p.name,alt:p.name}).addTo(facilitiesLayer).bindPopup(`<strong>${esc(p.name)}</strong><br>Illustrative location, not a verified facility.<br>No shelter or road-access status is available.`));if(state.layer==='routes')drawRoutes();}
}
function drawRoutes(){if(!map)return;routeLayer.clearLayers();state.routes.forEach((route,i)=>{const chosen=i===state.routeSelected;L.geoJSON(route.geometry,{style:{color:chosen?'#386eab':'#899ea3',weight:chosen?5:3,opacity:chosen?.95:.6,dashArray:chosen?'':'6 5'}}).addTo(routeLayer).bindTooltip(`Route ${String.fromCharCode(65+i)} · ${num(route.distance/1000,1)} km${state.mode==='scenario'?' · illustrative exposure only':''}`);});}
function renderLocal(){const panel=$('#localPanel'),r=getRegion(state.selected);panel.hidden=state.layer==='risk';if(panel.hidden)return;
 if(state.layer==='infrastructure'){panel.innerHTML=`<div class="local-heading"><div><h3>${r.name} · community context</h3><p>Illustrative places help explain who could be affected. Facility verification is pending.</p></div><span class="source-badge">DEMONSTRATION</span></div><div class="places-list">${examplePlaces[r.id].map(p=>`<button class="place-row" data-place="${p.id}"><span class="place-type">${p.kind==='hospital'?'+':p.kind==='school'?'▥':'⌂'}</span><span><strong>${p.name}</strong><small>${state.mode==='scenario'?'Compare with illustrative flood zones':'No local flood observations connected'}</small></span></button>`).join('')}</div><p style="margin-top:12px;margin-bottom:0">OpenStreetMap facility requests were unavailable during setup. These points are deliberately labelled as examples; they do not represent a verified facility inventory.</p>`;$$('[data-place]').forEach(b=>b.onclick=()=>{const p=examplePlaces[r.id].find(p=>p.id===b.dataset.place);map?.setView([p.lat,p.lng],16);});return;}
 panel.innerHTML=`<div class="local-heading"><div><h3>Which route has less exposure?</h3><p>A school-to-home example in ${r.name}. Compare road geometry with an illustrative storm.</p></div><span class="source-badge">ROUTE EXPLORER</span></div><div class="route-selects"><div><label>FROM</label><strong style="font-size:14px;font-weight:500">School · example origin</strong></div><div><label>TO</label><strong style="font-size:11px;font-weight:500">Home area · example destination</strong></div><button id="compareBtn" class="primary-button">${state.routes.length?'Reload routes':'Compare routes'}</button></div><div id="routeResults" class="route-results"></div><div id="routeInfo" class="route-info">${state.mode==='source'?'Source data does not include road closures or observed local inundation. Routes are not ranked for safety. Switch to Storm scenario to explore simulated exposure.':'Flood zones and endpoints are illustrative. Routes are driving paths, not pedestrian evacuation advice.'}</div>`;$('#compareBtn').onclick=loadRoutes;renderRoutes();
}
async function loadRoutes(){const id=state.selected;$('#compareBtn').disabled=true;$('#compareBtn').textContent='Loading…';try{let data;try{data=await json(`data/${id}-routes.json`,6000);}catch{data=await json(routeUrls[id],18000);}if(state.selected!==id)return;if(data.code!=='Ok'||!data.routes?.length)throw Error('No route returned');state.routes=data.routes.slice(0,3);state.routeSelected=0;drawRoutes();renderRoutes();if(map)map.fitBounds(L.geoJSON(state.routes[0].geometry).getBounds(),{padding:[55,55],maxZoom:15});}catch(e){if(state.selected===id){$('#routeResults').innerHTML='<p>Routing service unavailable. Try again, or inspect the example locations on the map. No route has been invented.</p>';toast('Route geometry could not be retrieved.');}}finally{if(state.selected===id&&$('#compareBtn')){$('#compareBtn').disabled=false;$('#compareBtn').textContent='Reload routes';}}}
function renderRoutes(){if(!$('#routeResults')||!state.routes.length)return;const r=getRegion(state.selected),z=r.zones.map(z=>({...z,radius:z.radius*Math.sqrt(state.rainFactor)}));const exposures=state.routes.map(route=>routeExposure(route.geometry.coordinates,z).fraction);const min=Math.min(...exposures);$('#routeResults').innerHTML=state.routes.map((route,i)=>`<button class="route-option ${i===state.routeSelected?'active':''}" data-route="${i}"><strong>Route ${String.fromCharCode(65+i)} <span style="float:right">${num(route.distance/1000,1)} km</span></strong><small>${state.mode==='scenario'?`${num(exposures[i]*100)}% severity-weighted scenario overlap${state.routes.length>1&&exposures[i]===min?' · lower of returned options':''}`:'Road path only · flood safety unknown'}</small></button>`).join('');if(state.routes.length===1)$('#routeResults').insertAdjacentHTML('beforeend','<p>Only one route was returned; no alternative is available for comparison.</p>');$$('[data-route]').forEach(b=>b.onclick=()=>{state.routeSelected=Number(b.dataset.route);drawRoutes();renderRoutes();});}
function sourceCard(number,title,badge,text,fields,url,label){return `<article class="source-card"><div class="source-top"><span class="source-number" aria-hidden="true"></span><span class="source-badge">${badge}</span></div><h3>${title}</h3><p>${text}</p><dl>${fields.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a></article>`;}
